#include <list>
#include <iostream>

int main() {
    std::list<int> L = {1, 4, 2, 4, 3, 4};

    // Efficiently remove all occurrences of '4'
    L.remove(4); 

    // Efficiently remove all odd numbers (using lambda predicate)
    L.remove_if([](int x) { return x % 2 != 0; });

    // Output: 2
    for (int x : L) {
        std::cout << x << " ";
    }
    std::cout << "\n";
}
